INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_594adeaf4c484bf9b095', 'Canadian International College', 'الكلية الكندية الدولية', 'CIC', 'canadian-international-college', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'Sheikh Zayed City', 'مدينة الشيخ زايد', 'Canadian International College (CIC) offers education that combines academic study with practical application, with a partnership with Canada''s Cape Breton University that allows students to earn an accredited Canadian bachelor''s degree alongside the Egyptian degree in eligible programs. The college focuses on hands-on training and projects linked to the job market, with smart classrooms and modern labs on its New Cairo and Sheikh Zayed campuses. It also offers opportunities to study or go on exchange in Canada, along with a variety of student activities and clubs, including the Student Union, AIESEC and Hult Prize, giving students a university experience that brings together study, training and student life.', 'تقدم الكلية الكندية الدولية برامج تعليمية على النمط الكندي بالتعاون مع مؤسسات دولية.', NULL, NULL, NULL, '/img/universities/canadian-international-college/logo.png', '/img/universities/canadian-international-college/cover.jpg', 2004, 'Sheikh Zayed, Giza, Egypt', 'الشيخ زايد، الجيزة، مصر', NULL, NULL, 1, FALSE, FALSE, FALSE, NULL, NULL, 'https://maps.google.com/?q=Canadian+International+College', '2026-10-13T22:57:28.689Z', '2026-10-13T22:57:28.689Z', '2026-10-08T03:56:41.290Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED.