INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_13338d5aa0654fa79b0e', 'University of London Egypt', 'جامعة لندن مصر', 'UoL', 'university-of-london-egypt', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'New Administrative Capital', 'العاصمة الإدارية الجديدة', 'The University of London gives students in Egypt the chance to earn a University of London degree through its recognized teaching center at the European Universities in Egypt (EUE) in the New Administrative Capital. Its programs cover a range of fields such as computer science, business administration, economics and finance, law, psychology, and politics and international relations, including programs under the academic direction of leading British institutions such as the London School of Economics (LSE). Students benefit from studying in Egypt while earning a qualification from the University of London, along with foundation programs that help them prepare for university study. Some programs also offer the chance to study locally while drawing on international academic resources and expertise.', 'تتيح جامعة لندن للطلاب في مصر الحصول على درجة جامعية من جامعة لندن من خلال مركزها التعليمي المعتمد في الجامعات الأوروبية في مصر (EUE) بالعاصمة الإدارية الجديدة. وتتميز البرامج بتنوعها في مجالات مثل علوم الحاسب، إدارة الأعمال، الاقتصاد والتمويل، القانون، علم النفس والسياسة والعلاقات الدولية، مع وجود برامج ذات توجيه أكاديمي من مؤسسات بريطانية مرموقة مثل London School of Economics (LSE). ويستفيد الطلاب من الدراسة داخل مصر مع الحصول على مؤهل من جامعة لندن، إلى جانب برامج تأسيسية تساعد الطلاب على الاستعداد للدراسة الجامعية. كما توفر بعض البرامج فرصا للدراسة محليا مع إمكانية الاستفادة من الموارد والخبرة الأكاديمية الدولية.', NULL, NULL, NULL, NULL, NULL, 2021, 'New Administrative Capital, Cairo, Egypt', 'العاصمة الإدارية الجديدة، القاهرة، مصر', NULL, NULL, 3, FALSE, FALSE, FALSE, NULL, NULL, 'https://maps.google.com/?q=University+of+London+Egypt', '2026-10-13T22:57:28.689Z', '2026-10-13T22:57:28.689Z', '2026-10-09T16:04:56.647Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
