INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_13e2c1693c294ccab007', 'Kayan University', 'جامعة كيان', NULL, 'kayan-university', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'New Administrative Capital', 'العاصمة الإدارية الجديدة', 'Kayan University is the first civilian university launched by the Egyptian Armed Forces, established under the law creating Kayan University of Applied Sciences. It is based inside the Egyptian Military Academy in the New Administrative Capital and takes its first intake in October 2026. It opens with six faculties: medicine, dentistry, pharmacy, physical therapy, engineering, and computers and artificial intelligence, supported by an integrated university hospital, a medical simulation center and a physical therapy and rehabilitation center. Admission is open to holders of Thanaweya Amma, Al-Azhar and equivalent certificates, and includes fitness, psychological and aptitude tests and a personal interview.', 'جامعة كيان هي أول جامعة مدنية تطلقها القوات المسلحة المصرية، وأُنشئت بموجب قانون إنشاء جامعة كيان للعلوم التطبيقية. تقع داخل الأكاديمية العسكرية بالعاصمة الإدارية الجديدة، وتستقبل أول دفعة من طلابها في أكتوبر 2026. تبدأ بست كليات هي الطب وطب الأسنان والصيدلة والعلاج الطبيعي والهندسة والحاسبات والذكاء الاصطناعي، مع مستشفى جامعي متكامل ومركز للمحاكاة الطبية ومركز للعلاج الطبيعي والتأهيل. يُقبل بها حاصلو الثانوية العامة والأزهرية والشهادات المعادلة، ويشمل القبول اختبارات اللياقة البدنية والاختبارات النفسية واختبارات القدرات والمقابلة الشخصية.', NULL, NULL, NULL, NULL, NULL, 2026, 'Egyptian Military Academy, New Administrative Capital', 'الأكاديمية العسكرية، العاصمة الإدارية الجديدة', NULL, NULL, 2, FALSE, FALSE, FALSE, NULL, NULL, NULL, '2026-10-09T23:52:37.396Z', '2026-10-09T23:52:37.396Z', '2026-10-09T23:53:08.180Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO "Faculty" (id, "universityId", name, "nameAr", slug, description, "descriptionAr", "imageUrl", "sortOrder", "createdAt", "updatedAt") VALUES ('fac_2c213172c09e44d7b7b5', 'univ_13e2c1693c294ccab007', 'Faculty of Medicine', 'كلية الطب', 'faculty-of-medicine', NULL, NULL, NULL, 0, '2026-10-13T23:00:49.747Z', '2026-10-13T23:00:49.747Z');
INSERT INTO "Program" (id, "universityId", "facultyId", name, "nameAr", slug, description, "descriptionAr", "studyLevel", "fieldOfStudy", "durationMonths", "durationLabel", "durationLabelAr", "tuitionFee", "tuitionPeriod", currency, "applicationFee", "applicationFeeWaived", "minGradePercent", "coopAvailable", tags, "isPublished", "createdAt", "updatedAt") VALUES ('prog_30928628ce804e52a691', 'univ_13e2c1693c294ccab007', 'fac_2c213172c09e44d7b7b5', 'Medicine', 'الطب البشري', 'medicine', 'Admission: minimum 90% (science stream), plus fitness, psychological and aptitude tests (English, computing, chemistry, biology and an intelligence test) and a personal interview. Applicants must be no older than 21 on 1 November 2026.', 'القبول: حد أدنى 90% (شعبة علمي علوم)، واجتياز اختبارات اللياقة البدنية والاختبارات النفسية واختبارات القدرات (اللغة الإنجليزية والحاسب والكيمياء والأحياء واختبار الذكاء) والمقابلة الشخصية. ويُشترط ألا يزيد سن المتقدم على 21 عامًا في 1 نوفمبر 2026.', 'BACHELOR'::"StudyLevel", 'medicine', 84, '7 years (5 years of study + 2-year internship)', '7 سنوات (5 سنوات دراسة + سنتان امتياز)', 245000, 'YEAR'::"TuitionPeriod", 'EGP', NULL, FALSE, 90, FALSE, ARRAY[]::"ProgramTag"[], TRUE, '2026-10-13T23:00:49.747Z', '2026-10-13T23:00:49.747Z');
