INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_2262e036d3504e23ba57', 'New Mansoura University', 'جامعة المنصورة الجديدة', 'NMU', 'new-mansoura-university', 'NATIONAL'::"UniversityType", 'Egypt', 'مصر', 'New Mansoura', 'المنصورة الجديدة', 'NMU offers modern multidisciplinary education with advanced facilities and healthcare focus.', 'جامعة المنصورة الجديدة هي جامعة أهلية غير هادفة للربح، تقع في مدينة المنصورة الجديدة، وتقدم تجربة تعليمية حديثة تعتمد على التعلم القائم على المشروعات والتطبيق العملي، مع برامج في مجالات متنوعة تلائم احتياجات سوق العمل. يتميز الحرم الجامعي بتصميم حديث ويضم معامل متخصصة، مستشفى جامعي، ومرافق تعليمية ورياضية متطورة. كما توفر الجامعة سكنًا طلابيًا داخل الحرم، إلى جانب مطاعم وخدمات طلابية وملاعب ومناطق للأنشطة. وتهتم الجامعة بالابتكار والبحث العلمي والتدريب، مع توفير بيئة جامعية تساعد الطلاب على الجمع بين الدراسة والحياة الطلابية في مكان واحد.', NULL, NULL, NULL, '/img/universities/new-mansoura-university/logo.png', '/img/universities/new-mansoura-university/cover.jpg', 2020, 'New Mansoura, Dakahlia, Egypt', 'المنصورة الجديدة، الدقهلية، مصر', NULL, NULL, 1, FALSE, FALSE, FALSE, NULL, NULL, 'https://maps.google.com/?q=New+Mansoura+University', '2026-10-13T22:57:28.689Z', '2026-10-13T22:57:28.689Z', '2026-10-07T17:07:37.621Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description