INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_4401c731bc82456c9d51', 'New Alamein International University', 'جامعة العلمين الجديدة الدولية', 'NAU', 'new-alamein-international-university', 'NATIONAL'::"UniversityType", 'Egypt', 'مصر', 'New Alamein', 'العلمين الجديدة', 'New Alamein International University is a non-profit national university in New Alamein City, offering a modern university experience based on interdisciplinary education, project-based learning and practical application. It benefits from its location in New Alamein City, with a modern campus that includes advanced labs and learning and sports facilities, as well as on-campus student housing. The university also offers a variety of student activities and opportunities for training and cooperation with different institutions and companies, with a clear emphasis on innovation and scientific research. The nature of the campus and the city gives students the chance to enjoy a modern university environment that brings together study and student life.', 'توفر جامعة العلمين الجديدة الدولية برامج بمعايير دولية في الطب والهندسة وإدارة الأعمال.', NULL, NULL, NULL, '/img/universities/new-alamein-international-university/logo.png', '/img/universities/new-alamein-international-university/cover.jpg', 2020, 'New Alamein City, Matrouh, Egypt', 'مدينة العلمين الجديدة، مطروح، مصر', NULL, NULL, 0, FALSE, FALSE, FALSE, NULL, NULL, 'https://maps.google.com/?q=New+Alamein+International+University', '2026-10-13T22:57:28.689Z', '2026-10-13T22:57:28.689Z', '2026-10-01T08:35:51.570Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."n