INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_9b5243d7b0cf450b9475', 'Al Salam University', 'جامعة السلام', 'SalamU', 'al-salam-university', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'Assiut', 'أسيوط', 'Al Salam University in Egypt is a private university in the heart of the Delta, in Gharbia Governorate, founded in 2018. The university focuses on combining academic excellence with practical application, providing a modern learning environment that supports students and prepares them for the job market. It offers a variety of scholarships for high achievers, including scholarships for top Thanaweya Amma students as well as academic and sports excellence scholarships. The university also provides student transportation and fully serviced hotel-style housing. Campus life includes a variety of activities and sports facilities, with opportunities to take part in competitions and student events.', 'جامعة السلام بمصر هي جامعة خاصة تقع في قلب منطقة الدلتا بمحافظة الغربية، وتأسست عام 2018. تركز الجامعة على الجمع بين التميز الأكاديمي والتطبيق العملي، مع توفير بيئة تعليمية حديثة لدعم الطلاب وتأهيلهم لسوق العمل. وتتميز بتقديم منح دراسية متنوعة للمتفوقين، تشمل منحا لاوائل الثانوية العامة، إلى جانب منح التفوق الدراسي والرياضي. كما توفر الجامعة خدمة الانتقالات للطلاب، بالإضافة إلى سكن فندقي متكامل الخدمات. وتضم الحياة الجامعية أنشطة ومرافق رياضية متنوعة، مع فرص للمشاركة في المسابقات والفعاليات الطلابية.', NULL, NULL, NULL, NULL, '/img/universities/al-salam-university/cover.jpg', 2018, 'Assiut, Egypt', 'أسيوط، مصر', NULL, NULL, 1, FALSE, FALSE, FALSE, NULL, NULL, 'https://maps.google.com/?q=Al+Salam+University+Egypt', '2026-10-13T22:57:28.689Z', '2026-10-13T22:57:28.689Z', '2026-10-08T06:36:19.288Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
