INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_c31b5768908f4930afbb', 'King Salman International University', 'جامعة الملك سلمان الدولية', 'KSIU', 'king-salman-international-university', 'NATIONAL'::"UniversityType", 'Egypt', 'مصر', 'South Sinai', 'جنوب سيناء', 'King Salman International University is a non-profit national university offering a distinctive university experience in South Sinai through three branches in El Tor, Sharm El Sheikh and Ras Sedr. It stands out for its smart campus, with modern labs and classrooms that support hands-on learning and new specializations, and a focus on innovation and scientific research. Among its highlights is hotel-style housing on campus, along with restaurants, student services, sports facilities and swimming pools. The university also offers a varied student life through sports, cultural and recreational activities, making study a complete experience that combines education and campus life in a unique setting in South Sinai.', 'جامعة الملك سلمان الدولية هي جامعة أهلية غير هادفة للربح تقدم تجربة جامعية مختلفة في جنوب سيناء من خلال ثلاثة أفرع في الطور وشرم الشيخ ورأس سدر. وتتميز بحرم جامعي ذكي يضم معامل وفصولا حديثة تدعم التعلم العملي والتخصصات الحديثة، مع التركيز على الابتكار والبحث العلمي. ومن أبرز مميزاتها السكن الفندقي داخل الحرم، إلى جانب المطاعم والخدمات الطلابية والمرافق الرياضية وحمامات السباحة. كما توفر الجامعة حياة طلابية متنوعة من خلال الأنشطة الرياضية والثقافية والترفيهية، مما يجعل الدراسة تجربة متكاملة تجمع بين التعليم والحياة الجامعية في بيئة مميزة بجنوب سيناء.', NULL, NULL, NULL, '/img/universities/king-salman-international-university/logo.png', '/img/universities/king-salman-international-university/cover.jpg', 2020, 'South Sinai, Egypt (Ras Sedr, Sharm El Sheikh, El-Tor campuses)', 'جنوب سيناء، مصر (فروع رأس سدر وشرم الشيخ والطور)', NULL, NULL, 2, FALSE, FALSE, FALSE, NULL, NULL, 'https://maps.google.com/?q=King+Salman+International+University', '2026-10-13T22:57:28.689Z', '2026-10-13T22:57:28.689Z', '2026-10-08T07:49:44.769Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
