INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_8951edaf7f944c089d79', 'Cairo National University', 'جامعة القاهرة الأهلية', 'CNU', 'cairo-national-university', 'NATIONAL'::"UniversityType", 'Egypt', 'مصر', '6th of October City', 'مدينة 6 أكتوبر', 'Cairo National University is a national (ahleya) university affiliated with Cairo University, established by Presidential Decree No. 245 of 2025 and located in 6th of October City. The strategic plan of Cairo National University is based on an analysis of the current situation of Cairo University, while taking into consideration the strategic vision for higher education in the Arab Republic of Egypt, which is derived from Egypt’s Vision 2030. This approach allows for the development of an ambitious, effective, and implementable strategy that aims to achieve excellence as a primary objective. It also reflects the available and anticipated resources and builds upon the historical strengths of Cairo University, while developing new fields and programs capable of moving the university toward new levels and horizons.', 'جامعة القاهرة الأهلية جامعة أهلية تابعة لجامعة القاهرة، أُنشئت بقرار رئيس الجمهورية رقم 245 لسنة 2025، ومقرها مدينة 6 أكتوبر. تعتمد الخطة الاستراتيجية للجامعة الأهلية لجامعة القاهرة على تحليل الوضع الحالي لجامعة القاهرة مع الاخذ في الحسبان الرؤية الاستراتيجية للتعليم العالي في جمهورية مصر العربية المستمد من رؤية مصر 2030 بما يسمح باعداد استراتيجية جريئة وفعالة وقلبلة للتنفيذ تعمل على تحقيق التمييز كهدف رئيسي وتعكس المدخلات المتاحة والمتوقعة للبناء على نقاط القوة التاريخية لجامعة القاهرة مع تطوير مجالات وبرامج جديدة تستطيع ان تنقل الجامعة الي مستويات وافاق مختلفة.', NULL, NULL, 'https://cnu.cu.edu.eg', '/img/universities/cairo-national-university/logo.png', '/img/universities/cairo-national-university/cover.jpg', 2025, 'Dahshur Link Road, 6th of October City', 'طريق وصلة دهشور، مدينة 6 أكتوبر', NULL, NULL, 4, FALSE, FALSE, FALSE, NULL, NULL, NULL, '2026-10-13T06:34:28.755Z', '2026-10-13T06:34:28.755Z', '2026-10-13T17:51:36.699Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
