INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_93177a53c0314f5288c3', 'Arab Academy for Science, Technology & Maritime Transport', 'الأكاديمية العربية للعلوم والتكنولوجيا والنقل البحري', 'AASTMT', 'arab-academy-for-science-technology-and-maritime-transport', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'Alexandria', 'الإسكندرية', 'The Arab Academy for Science, Technology and Maritime Transport is an educational institution affiliated with the League of Arab States. Founded in 1972, it offers study programs across a wide range of fields. Its specializations include engineering, computing and information technology, business administration, transport and logistics, and language and media, along with a number of medical and health programs and newer fields such as artificial intelligence. The Academy has branches in several Egyptian cities, including Alexandria, Cairo, El Alamein, Port Said and Aswan. Study combines academic education with practical application and training, with an emphasis on scientific research, innovation and international cooperation.', 'الأكاديمية العربية للعلوم والتكنولوجيا والنقل البحري هي مؤسسة تعليمية تابعة لجامعة الدول العربية، تأسست عام 1972 وتقدم برامج دراسية في مجموعة واسعة من المجالات. تشمل تخصصاتها الهندسة، والحاسبات وتكنولوجيا المعلومات، وإدارة الأعمال، والنقل واللوجستيات، واللغة والإعلام، إلى جانب عدد من البرامج الطبية والصحية والتخصصات الحديثة مثل الذكاء الاصطناعي. وتنتشر فروع الأكاديمية في عدد من المدن المصرية، من بينها الإسكندرية والقاهرة والعلمين وبورسعيد وأسوان. وتركز الدراسة على الجمع بين التعليم الأكاديمي والتطبيق العملي والتدريب، مع الاهتمام بالبحث العلمي والابتكار والتعاون الدولي.', NULL, NULL, NULL, NULL, '/img/universities/arab-academy-for-science-technology-and-maritime-transport/cover.jpg', 1972, 'Abu Qir, Alexandria, Egypt (Main Campus)', 'أبو قير، الإسكندرية، مصر (الحرم الرئيسي)', NULL, NULL, 1, FALSE, FALSE, FALSE, NULL, NULL, 'https://maps.google.com/?q=AASTMT+Abu+Qir', '2026-10-13T22:57:28.689Z', '2026-10-13T22:57:28.689Z', '2026-10-11T16:15:53.559Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
