INSERT INTO "Program" (id, "universityId", "facultyId", name, "nameAr", slug, description, "descriptionAr", "studyLevel", "fieldOfStudy", "durationMonths", "durationLabel", "durationLabelAr", "tuitionFee", "tuitionPeriod", currency, "applicationFee", "applicationFeeWaived", "minGradePercent", "coopAvailable", tags, "isPublished", "createdAt", "updatedAt") VALUES ('prog_1f0a3ba0135f4b32a77c', 'univ_93177a53c0314f5288c3', 'fac_5f4d92498b134a2ebe39', 'Marine Engineering Technology', 'تكنولوجيا الهندسة البحرية', 'marine-engineering-technology', 'Per term. Egypt and Sudan: Category A $4,920 · B $5,680 · C $6,440, paid in Egyptian pounds at EGP 23 per dollar (the fee shown is the highest category, $6,440). Other nationalities: Category A $5,795 · B $6,270 · C $7,030. Fees rise by $150 a year, with total increases capped at 15% a year.', 'للترم الواحد. مصر والسودان: فئة (أ) 4,920 دولار · (ب) 5,680 دولار · (ج) 6,440 دولار، تُدفع بالجنيه المصري بسعر 23 جنيهًا للدولار (المصروفات المعروضة لأعلى فئة، 6,440 دولار). أبناء الدول الأخرى: فئة (أ) 5,795 دولار · (ب) 6,270 دولار · (ج) 7,030 دولار. تزيد المصروفات 150 دولارًا سنويًا، على ألا تتجاوز الزيادة الإجمالية 15% سنويًا.', 'BACHELOR'::"StudyLevel", 'engineering', NULL, NULL, NULL, 148120, 'TERM'::"TuitionPeriod", 'EGP', NULL, FALSE, NULL, FALSE, ARRAY[]::"ProgramTag"[], TRUE, '2026-10-13T23:00:49.753Z', '2026-10-13T23:00:49.753Z');
