INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_ce37287123db4fcf88cb', 'Ain Shams National University', 'جامعة عين شمس الأهلية', 'NASU', 'ain-shams-national-university', 'NATIONAL'::"UniversityType", 'Egypt', 'مصر', 'New Administrative Capital', 'العاصمة الإدارية الجديدة', 'Established by Presidential Decree No. 246 of 2025 as a non-profit national (ahleya) university. Ain Shams National University was established as a modern extension of the legacy of Ain Shams University, one of Egypt''s oldest and most prestigious universities. It combines a solid academic heritage with a contemporary vision that keeps pace with the demands of the era and the job market. The university is located in the New Administrative Capital, in the Valley of Learning & Innovation, on a modern, well-equipped campus that provides an inspiring learning environment for its founding generation of students. The university comprises four academic fields containing ten modern programs in medicine, engineering, computing, and business, designed to prepare graduates capable of leading the future and contributing to the nation''s advancement.', 'أُنشئت بقرار رئيس الجمهورية رقم 246 لسنة 2025 جامعةً أهلية غير هادفة للربح. تأسست جامعة عين شمس الأهلية لتكون امتداداً حديثاً لإرث جامعة عين شمس العريقة، إحدى أقدم وأعرق الجامعات المصرية. تجمع الجامعة بين رصيدٍ أكاديمي راسخ ورؤيةٍ معاصرة تواكب متطلّبات العصر وسوق العمل. تقع الجامعة في العاصمة الإدارية الجديدة بوادي التعلّم والابتكار، في حرمٍ جامعي حديث ومجهّز بأحدث الإمكانات، ليوفّر بيئة تعليمية مُلهمة تحتضن الجيل المؤسّس من طلابها. تضمّ الجامعة أربعة مجالات أكاديمية تحتوي على عشرة برامج حديثة في الطب والهندسة والحاسبات والأعمال، صُمّمت لإعداد خرّيجين قادرين على قيادة المستقبل والإسهام في نهضة الوطن.', NULL, NULL, NULL, '/img/universities/ain-shams-national-university/logo.png', '/img/universities/ain-shams-national-university/cover.jpg', 2025, 'Valley of Learning & Innovation, New Administrative Capital', 'وادي التعلم والابتكار، العاصمة الإدارية الجديدة', NULL, NULL, 1, FALSE, FALSE, FALSE, NULL, NULL, NULL, '2026-10-13T06:34:28.755Z', '2026-10-13T06:34:28.755Z', '2026-10-13T06:35:11.293Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO "Faculty" (id, "universityId", name, "nameAr", slug, description, "descriptionAr", "imageUrl", "sortOrder", "createdAt", "updatedAt") VALUES ('fac_319201ff30374b3ea237', 'univ_ce37287123db4fcf88cb', 'Faculty of Medicine', 'كلية الطب', 'faculty-of-medicine', NULL, NULL, NULL, 0, '2026-10-13T23:00:49.755Z', '2026-10-13T23:00:49.755Z');
INSERT INTO "Program" (id, "universityId", "facultyId", name, "nameAr", slug, description, "descriptionAr", "studyLevel", "fieldOfStudy", "durationMonths", "durationLabel", "durationLabelAr", "tuitionFee", "tuitionPeriod", currency, "applicationFee", "applicationFeeWaived", "minGradePercent", "coopAvailable", tags, "isPublished", "createdAt", "updatedAt") VALUES ('prog_2685b7137b844d9cab03', 'univ_ce37287123db4fcf88cb', 'fac_319201ff30374b3ea237', 'Medicine & Surgery', 'بكالوريوس الطب والجراحة', 'medicine-and-surgery', 'An integrated program that continuously develops its educational systems in line with the latest teaching and assessment methods, enabling students to acquire the competencies needed for their future roles as practicing physicians. The program combines medical education, scientific research and community service through a modern university hospital in Obour City.', 'برنامج متكامل يطوّر أنظمته التعليمية باستمرار بما يواكب أحدث أساليب التدريس والتقييم، ليكتسب الطلاب الكفاءات اللازمة لأدوارهم المستقبلية كأطباء ممارسين. يجمع البرنامج بين التعليم الطبي والبحث العلمي وخدمة المجتمع عبر مستشفى جامعي حديث في مدينة العبور.', 'BACHELOR'::"StudyLevel", 'medicine', NULL, NULL, NULL, NULL, 'YEAR'::"TuitionPeriod", 'EGP', NULL, FALSE, NULL, FALSE, ARRAY[]::"ProgramTag"[], TRUE, '2026-10-13T23:00:49.755Z', '2026-10-13T23:00:49.755Z');
INSERT INTO "Faculty" (id, "universityId", name, "nameAr", slug, description, "descriptionAr", "imageUrl", "sortOrder", "createdAt", "updatedAt") VALUES ('fac_a8057b7530024f2db340', 'univ_ce37287123db4fcf88cb', 'Faculty of Engineering', 'كلية الهندسة', 'faculty-of-engineering', NULL, NULL, NULL, 1, '2026-10-13T23:00:49.755Z', '2026-10-13T23:00:49.755Z');
INSERT INTO "Program" (id, "universityId", "facultyId", name, "nameAr", slug, description, "descriptionAr", "studyLevel", "fieldOfStudy", "durationMonths", "durationLabel", "durationLabelAr", "tuitionFee", "tuitionPeriod", currency, "applicationFee", "applicationFeeWaived", "minGradePercent", "coopAvailable", tags, "isPublished", "createdAt", "updatedAt") VALUES ('prog_265cde8a92d543e7b387', 'univ_ce37287123db4fcf88cb', 'fac_a8057b7530024f2db340', 'Civil Engineering & Environmental Informatics', 'الهندسة المدنية والمعلوماتية البيئية', 'civil-engineering-and-environmental-informatics', 'The Civil Engineering and Environmental Informatics program focuses on the scientific assessment and development of engineering solutions for civil engineering challenges with environmental impacts. These include safe drinking water, wastewater treatment, solid and hazardous waste disposal, air and noise pollution, human and environmental health risk management, and pollution prevention. Given the complexity of these challenges and the vast amounts of associated data, informatics becomes essential. The program aims to prepare civil and environmental engineers capable of utilizing advanced modern technologies while developing the tools to predict and better manage environmental needs, emphasizing clean environments and green infrastructure planning in alignment with smart city concepts. Graduates will develop critical analytical, decision-making, and data modeling skills using appropriate tools, including artificial intelligence.', 'يغطّي برنامج الهندسة المدنية والمعلوماتية البيئية التقييم العلمي وتطوير الحلول الهندسية للمشكلات الخاصة بالهندسة المدنية التي تؤثّر على البيئة. وتشمل هذه المشكلات مياه الشرب الآمنة، ومعالجة مياه الصرف الصحي، والتخلّص من النفايات الصلبة والخطرة، وتلوّث الهواء الخارجي والداخلي والضوضاء الناتجة من وسائل النقل، وإدارة مخاطر الصحة البشرية والبيئية، والوقاية من التلوّث. ونظراً لتعقيد هذه المشكلات والكمّ الهائل من البيانات المتصلة بها، تصبح المعلوماتية ضرورية لتحويل البيانات الضخمة المعقّدة إلى حقائق قابلة للاستخدام. يهدف البرنامج إلى إعداد مهندسين مدنيين وبيئيين قادرين على استخدام التقنيات الحديثة والمتقدّمة، إلى جانب تطوير الأدوات اللازمة للتنبؤ بالاحتياجات البيئية والتعامل معها، من أجل توفير بيئات نظيفة والتخطيط لبنية تحتية خضراء تتوافق مع مفاهيم المدن الذكية. وسيطوّر الخريجون مهارات التحليل واتخاذ القرار ونمذجة البيانات باستخدام الأدوات المناسبة بما فيها الذكاء الاصطناعي.', 'BACHELOR'::"StudyLevel", 'engineering', NULL, NULL, NULL, NULL, 'YEAR'::"TuitionPeriod", 'EGP', NULL, FALSE, NULL, FALSE, ARRAY[]::"ProgramTag"[], TRUE, '2026-10-13T23:00:49.755Z', '2026-10-13T23:00:49.755Z');
INSERT INTO "Program" (id, "universityId", "facultyId", name, "nameAr", slug, description, "descriptionAr", "studyLevel", "fieldOfStudy", "durationMonths", "durationLabel", "durationLabelAr", "tuitionFee", "tuitionPeriod", currency, "applicationFee", "applicationFeeWaived", "minGradePercent", "coopAvailable", tags, "isPublished", "createdAt", "updatedAt") VALUES ('prog_f2d9a7fdeb734f35b19f', 'univ_ce37287123db4fcf88cb', 'fac_a8057b7530024f2db340', 'Computational Architecture & Intelligent Urban Design', 'العمارة الحاسوبية والتصميم العمراني الذكي', 'computational-architecture-and-intelligent-urban-design', 'The Digital Architecture and Intelligent Urban Design program is an integrated academic program designed to prepare architecture engineers capable of employing cutting-edge digital technologies and artificial intelligence in architectural and urban design. The program focuses on developing competencies in computational design, Building Information Modeling (BIM), Geographic Information Systems (GIS), Internet of Things (IoT), and smart city analytics. Through an interdisciplinary curriculum, students learn to apply digital design technologies, parametric modeling, generative design, and digital fabrication, while integrating virtual and augmented reality into design and construction processes. The program fosters critical and creative thinking, encouraging innovative solutions for energy efficiency and environmental sustainability.', 'برنامج هندسة العمارة الرقمية والتصميم العمراني الذكي هو برنامج متكامل يهدف إلى إعداد مهندسين معماريين يمتلكون القدرة على توظيف أحدث التقنيات الرقمية والذكاء الاصطناعي في مجالات التصميم المعماري والحضري. يركّز البرنامج على تطوير مهارات الطلاب في استخدام أدوات متقدّمة مثل التصميم الحسابي ونمذجة معلومات البناء (BIM) ونظم المعلومات الجغرافية (GIS) وإنترنت الأشياء وتحليلات المدن الذكية. من خلال منهج متعدّد التخصصات، يتعلّم الطلاب تطبيق تقنيات التصميم الرقمي والنمذجة البارامترية والتصميم التوليدي والتصنيع الرقمي، بالإضافة إلى دمج تقنيات الواقع الافتراضي والمعزّز في عمليات التصميم والإنشاء. ويعزّز البرنامج التفكير النقدي والإبداعي، ويشجّع على تبنّي حلول مبتكرة لتحقيق كفاءة الطاقة والاستدامة البيئية.', 'BACHELOR'::"StudyLevel", 'architecture', NULL, NULL, NULL, NULL, 'YEAR'::"TuitionPeriod", 'EGP', NULL, FALSE, NULL, FALSE, ARRAY[]::"ProgramTag"[], TRUE, '2026-10-13T23:00:49.755Z', '2026-10-13T23:00:49.755Z');
INSERT INTO "Program" (id, "universityId", "facultyId", name, "nameAr", slug, description, "descriptionAr", "studyLevel", "fieldOfStudy", "durationMonths", "durationLabel", "durationLabelAr", "tuitionFee", "tuitionPeriod", currency, "applicationFee", "applicationFeeWaived", "minGradePercent", "coopAvailable", tags, "isPublished", "createdAt", "updatedAt") VALUES ('prog_55f5a79e431f4edc9e73', 'univ_ce37287123db4fcf88cb', 'fac_a8057b7530024f2db340', 'Digital Manufacturing & Materials Engineering', 'هندسة التصنيع الرقمي والمواد', 'digital-manufacturing-and-materials-engineering', 'The Digital Manufacturing and Materials Engineering program integrates materials science with advanced manufacturing technologies, preparing students to meet the demands of future industries. The program emphasizes understanding the relationship between material composition, properties, and applications, enabling students to develop advanced materials for sectors such as mechanical systems, petroleum, medicine, electronics, and nanotechnology. Students acquire advanced skills in digital manufacturing, including process design, automation, smart systems, and quality assurance. The program equips graduates to innovate in material selection, optimize production systems, and enhance industrial process efficiency, aligning with global demand for sustainable and high-performance manufacturing.', 'يجمع برنامج التصنيع الرقمي وهندسة المواد بين علوم المواد والتقنيات الحديثة في التصنيع، بهدف إعداد الطلاب لمتطلبات الصناعة المستقبلية. يركّز البرنامج على فهم العلاقة بين تركيب المواد وخصائصها وتطبيقاتها، ممّا يمكّن الطلاب من تطوير مواد متقدّمة تُستخدم في قطاعات مثل الأنظمة الميكانيكية والبترول والطب والإلكترونيات وتقنيات النانو. يكتسب الطلاب مهارات متقدّمة في التصنيع الرقمي تشمل تصميم العمليات والأتمتة والأنظمة الذكية وضمان الجودة. ويُؤهّل البرنامج الخريجين للابتكار في اختيار المواد وتحسين أنظمة الإنتاج ورفع كفاءة العمليات الصناعية، لمواكبة الطلب العالمي على التصنيع الفعّال والمستدام.', 'BACHELOR'::"StudyLevel", 'engineering', NULL, NULL, NULL, NULL, 'YEAR'::"TuitionPeriod", 'EGP', NULL, FALSE, NULL, FALSE, ARRAY[]::"ProgramTag"[], TRUE, '2026-10-13T23:00:49.755Z', '2026-10-13T23:00:49.755Z');
INSERT INTO "Program" (id, "universityId", "facultyId", name, "nameAr", slug, description, "descriptionAr", "studyLevel", "fieldOfStudy", "durationMonths", "durationLabel", "durationLabelAr", "tuitionFee", "tuitionPeriod", currency, "applicationFee", "applicationFeeWaived", "minGradePercent", "coopAvailable", tags, "isPublished", "createdAt", "updatedAt") VALUES ('prog_6170e7d7eba94de2a91e', 'univ_ce37287123db4fcf88cb', 'fac_a8057b7530024f2db340', 'Electronics & Artificial Intelligence Engineering', 'هندسة الإلكترونيات والذكاء الاصطناعي', 'electronics-and-artificial-intelligence-engineering', 'The Electronics and Artificial Intelligence Engineering program is designed to meet the growing demand for skilled electronics and computer engineers in the local market. The rapid expansion of the electronics and AI sectors has outpaced the supply of qualified professionals. This program offers an interdisciplinary curriculum combining electronics engineering, computer engineering, and business knowledge. The program provides foundational knowledge across all areas of electronics and AI engineering such as software, algorithms, embedded systems, IoT, communication and network systems, digital systems, multimedia systems, and intelligent systems, alongside communication, design, development, and management skills that meet national, regional, and international labor market needs.', 'صُمّم برنامج هندسة الإلكترونيات والذكاء الاصطناعي لتلبية الطلب المتزايد على مهندسي الإلكترونيات والحاسوب في السوق المحلي، المتخصصين في تطبيقات هندسة الإلكترونيات والذكاء الاصطناعي. يشهد القطاعان نمواً متسارعاً يفوق العرض من المواهب الجديدة. ويقدّم البرنامج مزيجاً متعدّد التخصصات من هندسة الإلكترونيات وهندسة الحاسوب بالإضافة إلى المعرفة التجارية. يوفّر البرنامج المعرفة الأساسية في جميع مجالات هندسة الإلكترونيات والذكاء الاصطناعي مثل البرمجيات والخوارزميات والنظم المدمجة وإنترنت الأشياء ونظم الاتصالات والشبكات والنظم الرقمية والنظم متعدّدة الوسائط والنظم الذكية، إلى جانب مهارات الاتصال والتصميم والتطوير والإدارة، بما يلبّي متطلبات سوق العمل الوطنية والإقليمية والدولية.', 'BACHELOR'::"StudyLevel", 'engineering', NULL, NULL, NULL, NULL, 'YEAR'::"TuitionPeriod", 'EGP', NULL, FALSE, NULL, FALSE, ARRAY[]::"ProgramTag"[], TRUE, '2026-10-13T23:00:49.755Z', '2026-10-13T23:00:49.755Z');
INSERT INTO "Program" (id, "universityId", "facultyId", name, "nameAr", slug, description, "descriptionAr", "studyLevel", "fieldOfStudy", "durationMonths", "durationLabel", "durationLabelAr", "tuitionFee", "tuitionPeriod", currency, "applicationFee", "applicationFeeWaived", "minGradePercent", "coopAvailable", tags, "isPublished", "createdAt", "updatedAt") VALUES ('prog_ddd51d4fec1549bb9271', 'univ_ce37287123db4fcf88cb', 'fac_a8057b7530024f2db340', 'Robotics & Autonomous Systems Engineering', 'هندسة الروبوتات والأنظمة ذاتية القيادة', 'robotics-and-autonomous-systems-engineering', 'The Robotics and Autonomous Systems Engineering program focuses on preparing engineers capable of designing and developing intelligent robotic systems that operate autonomously and make independent decisions. The program integrates multiple disciplines, including mechanical engineering, electrical and electronics engineering, control systems engineering, software engineering, and artificial intelligence. These intelligent robotic systems are utilized across diverse fields, including industrial process automation, advanced robotic manufacturing, autonomous vehicles (cars, aircraft, and submarines), smart agriculture, robotic-assisted healthcare and remote surgery, smart home assistance systems, autonomous navigation, and search-and-rescue operations. The program aims to graduate professionals capable of leading the 4th and 5th Industrial Revolutions.', 'يركّز برنامج هندسة الروبوتات والأنظمة الذاتية على إعداد مهندسين قادرين على تصميم وتطوير أنظمة روبوتية ذكية تعمل بشكل مستقل وتتخذ القرارات ذاتياً. يدمج البرنامج بين تخصصات متعدّدة تشمل الهندسة الميكانيكية، والهندسة الكهربائية والإلكترونية، وهندسة التحكّم الآلي، وعلوم البرمجيات، والذكاء الاصطناعي، ممّا يمنح الطلاب خلفية علمية متكاملة ومهارات تقنية متقدّمة. تُستخدم هذه الأنظمة في مجالات عديدة منها أتمتة العمليات الصناعية، والتصنيع المتقدّم بالروبوتات، والسيارات والطائرات والغواصات ذاتية القيادة، والزراعة الذكية، والرعاية الصحية والجراحة عن بُعد، والأنظمة الذكية للمساعدة المنزلية، والملاحة الذاتية، وعمليات البحث والإنقاذ. ويهدف البرنامج إلى تخريج كوادر مؤهّلة لقيادة الثورة الصناعية الرابعة والخامسة.', 'BACHELOR'::"StudyLevel", 'engineering', NULL, NULL, NULL, NULL, 'YEAR'::"TuitionPeriod", 'EGP', NULL, FALSE, NULL, FALSE, ARRAY[]::"ProgramTag"[], TRUE, '2026-10-13T23:00:49.755Z', '2026-10-13T23:00:49.755Z');
INSERT INTO "Faculty" (id, "universityId", name, "nameAr", slug, description, "descriptionAr", "imageUrl", "sortOrder", "createdAt", "updatedAt") VALUES ('fac_93d2aa7cc57f4779b668', 'univ_ce37287123db4fcf88cb', 'Faculty of Computers, Information & Artificial Intelligence', 'كلية الحاسبات والمعلومات والذكاء الاصطناعي', 'faculty-of-computers-information-and-artificial-intelligence', NULL, NULL, NULL, 2, '2026-10-13T23:00:49.755Z', '2026-10-13T23:00:49.755Z');
INSERT INTO "Program" (id, "universityId", "facultyId", name, "nameAr", slug, description, "descriptionAr", "studyLevel", "fieldOfStudy", "durationMonths", "durationLabel", "durationLabelAr", "tuitionFee", "tuitionPeriod", currency, "applicationFee", "applicationFeeWaived", "minGradePercent", "coopAvailable", tags, "isPublished", "createdAt", "updatedAt") VALUES ('prog_ca4ac748d89d4ccda721', 'univ_ce37287123db4fcf88cb', 'fac_93d2aa7cc57f4779b668', 'Computer Science & Artificial Intelligence', 'علوم الحاسب والذكاء الاصطناعي', 'computer-science-and-artificial-intelligence', 'BSc Computer Science and Artificial Intelligence contains broad coverage of all major computer science topics as well as specialist modules in artificial intelligence. This foundation prepares graduates to be effective contributors to the field, capable of addressing complex challenges and driving technological innovation. By combining theoretical knowledge with practical skills and ethical considerations, graduates are well-equipped to contribute to the advancement of AI and its applications in various fields.', 'يتضمّن برنامج بكالوريوس علوم الحاسوب والذكاء الاصطناعي تغطيةً شاملةً لجميع مواضيع علوم الحاسب الرئيسية، بالإضافة إلى وحداتٍ متخصصة في الذكاء الاصطناعي. يُهيّئ هذا البرنامج الخريجين ليكونوا مساهمين فاعلين في مجال علوم الحاسب والذكاء الاصطناعي، قادرين على مواجهة التحديات المعقّدة ودفع عجلة الابتكار التكنولوجي. ومن خلال الجمع بين المعرفة النظرية والمهارات العملية والاعتبارات الأخلاقية، يكون الخريجون مؤهّلين تأهيلاً عالياً للمساهمة في تطوير الذكاء الاصطناعي وتطبيقاته في مختلف المجالات.', 'BACHELOR'::"StudyLevel", 'computer_science', NULL, NULL, NULL, NULL, 'YEAR'::"TuitionPeriod", 'EGP', NULL, FALSE, NULL, FALSE, ARRAY[]::"ProgramTag"[], TRUE, '2026-10-13T23:00:49.755Z', '2026-10-13T23:00:49.755Z');
INSERT INTO "Program" (id, "universityId", "facultyId", name, "nameAr", slug, description, "descriptionAr", "studyLevel", "fieldOfStudy", "durationMonths", "durationLabel", "durationLabelAr", "tuitionFee", "tuitionPeriod", currency, "applicationFee", "applicationFeeWaived", "minGradePercent", "coopAvailable", tags, "isPublished", "createdAt", "updatedAt") VALUES ('prog_a47b36a8a4dc44dd895e', 'univ_ce37287123db4fcf88cb', 'fac_93d2aa7cc57f4779b668', 'Data Science & Analytics', 'علوم البيانات والتحليلات', 'data-science-and-analytics', 'The modern world operates on a massive amount of data - from smartphones to smart homes. Data science is the field that exploits data to extract insights, solve real-world problems, and drive innovation. This program provides students with a foundation in the essential disciplines of computer science, statistics, and mathematics relevant to the analysis and processing of large, complex datasets. The program goes beyond conventional statistical analysis, addressing the full data lifecycle: from specification, acquisition, and cleaning, to storage, modeling, visualization, and data-informed decision-making.', 'يعتمد العالم الحديث على كمية هائلة من البيانات، من الهواتف الذكية إلى المنازل الذكية. علوم البيانات هو المجال الذي يستغلّ البيانات لاستخلاص الرؤى وحلّ مشاكل العالم الحقيقي ودفع الابتكار. يوفّر هذا البرنامج للطلاب أساساً في التخصصات الأساسية لعلوم الحاسب والإحصاء والرياضيات ذات الصلة بتحليل ومعالجة مجموعات البيانات الكبيرة والمعقّدة، ويتجاوز التحليل الإحصائي التقليدي ليتناول دورة حياة البيانات الكاملة، من التحديد والاكتساب والتنظيف، إلى التخزين والنمذجة والتصوّر واتخاذ القرارات المستندة إلى البيانات.', 'BACHELOR'::"StudyLevel", 'computer_science', NULL, NULL, NULL, NULL, 'YEAR'::"TuitionPeriod", 'EGP', NULL, FALSE, NULL, FALSE, ARRAY[]::"ProgramTag"[], TRUE, '2026-10-13T23:00:49.755Z', '2026-10-13T23:00:49.755Z');
INSERT INTO "Faculty" (id, "universityId", name, "nameAr", slug, description, "descriptionAr", "imageUrl", "sortOrder", "createdAt", "updatedAt") VALUES ('fac_476d34df030b467dbd28', 'univ_ce37287123db4fcf88cb', 'Faculty of Business', 'كلية الأعمال', 'faculty-of-business', NULL, NULL, NULL, 3, '2026-10-13T23:00:49.755Z', '2026-10-13T23:00:49.755Z');
INSERT INTO "Program" (id, "universityId", "facultyId", name, "nameAr", slug, description, "descriptionAr", "studyLevel", "fieldOfStudy", "durationMonths", "durationLabel", "durationLabelAr", "tuitionFee", "tuitionPeriod", currency, "applicationFee", "applicationFeeWaived", "minGradePercent", "coopAvailable", tags, "isPublished", "createdAt", "updatedAt") VALUES ('prog_d6b64a0a42a14a9ea0e7', 'univ_ce37287123db4fcf88cb', 'fac_476d34df030b467dbd28', 'Digital Marketing', 'التسويق الرقمي', 'digital-marketing', 'The Digital Marketing Program is a four-year undergraduate program designed to prepare students for leadership roles in the evolving digital economy. The program blends foundational business education with advanced digital marketing competencies, equipping students with the skills needed to thrive in data-driven, tech-enabled environments. Core areas of study include digital strategy, content creation, marketing analytics, e-commerce, online consumer behavior, and the application of artificial intelligence and machine learning in marketing. Supporting disciplines such as programming, design, and data interpretation are integrated to foster both technical proficiency and creative problem-solving.', 'يُعدّ برنامج التسويق الرقمي برنامجاً أكاديمياً متكاملاً يمتد لأربع سنوات، ويهدف إلى إعداد الكوادر المؤهّلة لتولّي مناصب قيادية في بيئة الاقتصاد الرقمي الحديث. يوفّر البرنامج مزيجاً متوازناً بين الأسس العلمية للإدارة والأعمال، والتخصصات المتقدّمة في مجالات التسويق الرقمي، بما يُمكّن الطلاب من اكتساب المهارات والمعارف الضرورية للعمل بكفاءة في مجالات قائمة على البيانات والتقنيات الحديثة. تشمل مجالات الدراسة الرئيسية الاستراتيجية الرقمية، وإنشاء المحتوى، وتحليلات التسويق، والتجارة الإلكترونية، وسلوك المستهلك الرقمي، بالإضافة إلى تطبيقات الذكاء الاصطناعي وتعلّم الآلة في العمليات التسويقية. ويُعزّز البرنامج هذا الإطار المعرفي من خلال إدماج مقررات ذات صلة وثيقة مثل البرمجة والتصميم وتحليل البيانات.', 'BACHELOR'::"StudyLevel", 'business_administration', NULL, NULL, NULL, NULL, 'YEAR'::"TuitionPeriod", 'EGP', NULL, FALSE, NULL, FALSE, ARRAY[]::"ProgramTag"[], TRUE, '2026-10-13T23:00:49.755Z', '2026-10-13T23:00:49.755Z');
INSERT INTO "Program" (id, "universityId", "facultyId", name, "nameAr", slug, description, "descriptionAr", "studyLevel", "fieldOfStudy", "durationMonths", "durationLabel", "durationLabelAr", "tuitionFee", "tuitionPeriod", currency, "applicationFee", "applicationFeeWaived", "minGradePercent", "coopAvailable", tags, "isPublished", "createdAt", "updatedAt") VALUES ('prog_2eca2068f06844828211', 'univ_ce37287123db4fcf88cb', 'fac_476d34df030b467dbd28', 'Financial Technology', 'التكنولوجيا المالية', 'financial-technology', 'The Financial Technology (FinTech) Program is designed to equip students with the essential knowledge and practical skills to excel in the rapidly evolving financial industry. This program combines core finance principles with cutting-edge technologies, enabling students to develop innovative solutions for financial challenges. Primary areas of study include data analytics, machine learning, blockchain technology, cryptocurrency, algorithmic trading, and fintech innovation. Through a blend of theoretical coursework and hands-on projects, students will gain proficiency in programming languages such as Python and R, allowing them to apply their learning to real-world financial scenarios. The program aims to provide a comprehensive understanding of financial markets and innovative technologies, develop expertise in applying advanced technologies to solve financial problems, and foster critical thinking and ethical decision-making.', 'صُمّم برنامج التكنولوجيا المالية لتزويد الطلاب بالمعرفة الأساسية والمهارات العملية اللازمة للتفوّق في القطاع المالي سريع التطوّر. يجمع هذا البرنامج بين مبادئ التمويل الأساسية والتقنيات المتطوّرة، ممّا يُمكّن الطلاب من تطوير حلول مبتكرة للتحديات المالية. وتشمل مجالات الدراسة الرئيسية تحليلات البيانات، والتعلّم الآلي، وتقنية البلوك تشين، والعملات المشفّرة، والتداول الخوارزمي، وابتكارات التكنولوجيا المالية. ومن خلال مزيج من المقررات الدراسية النظرية والمشاريع العملية، سيكتسب الطلاب إتقاناً في لغات البرمجة مثل بايثون وR، ممّا يُمكّنهم من تطبيق ما تعلّموه على السيناريوهات المالية الواقعية. يهدف البرنامج إلى توفير فهم شامل للأسواق المالية والتقنيات المبتكرة، وتطوير الخبرة في تطبيق التقنيات المتقدّمة لحلّ المشكلات المالية، وتعزيز التفكير النقدي واتخاذ القرارات الأخلاقية.', 'BACHELOR'::"StudyLevel", 'business_administration', NULL, NULL, NULL, NULL, 'YEAR'::"TuitionPeriod", 'EGP', NULL, FALSE, NULL, FALSE, ARRAY[]::"ProgramTag"[], TRUE, '2026-10-13T23:00:49.755Z', '2026-10-13T23:00:49.755Z');
