INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_c6c6cf73b0dc46438d04', 'MSA University', 'جامعة العلوم الحديثة والآداب (MSA)', 'MSA', 'msa-university', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', '6th of October City', 'مدينة 6 أكتوبر', 'October University for Modern Sciences and Arts (MSA) is a private university founded in 1996 in 6th of October City. It offers academic programs across a range of fields, including dentistry, pharmacy, biotechnology, engineering, computer science, management sciences, languages and translation, mass communication, arts and design, nutrition and food technology, and physical therapy. Study combines British academic standards with the requirements of university education in Egypt, with a focus on practical application and on developing research, analysis and problem-solving skills. The university also has academic partnerships with British universities and provides a learning environment with labs, training facilities and a variety of student activities.', 'تقدم جامعة MSA تعليمًا على النمط البريطاني في مصر، وتنمّي لدى الطلاب مهارات الكتابة والتحليل والتواصل لتحقيق نجاح مهني مستدام.', NULL, NULL, NULL, '/img/universities/msa-university/logo.png', '/img/universities/msa-university/cover.jpg', 1996, '6th of October City, Giza Governorate, Egypt', 'مدينة 6 أكتوبر، محافظة الجيزة، مصر', NULL, NULL, 3, FALSE, FALSE, FALSE, NULL, NULL, 'https://maps.google.com/?q=MSA+University+6th+of+October+City', '2026-10-13T22:57:28.689Z', '2026-10-13T22:57:28.689Z', '2026-10-08T07:26:06.643Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
