INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_8fcb80f9229340e08fac', 'Galala University', 'جامعة الجلالة', 'Galala', 'galala-university', 'NATIONAL'::"UniversityType", 'Egypt', 'مصر', 'Ain Sokhna', 'العين السخنة', 'Galala University is a non-profit national university in Galala City, offering a modern university experience that combines applied education with research and innovation. It offers more than 60 programs across a range of specializations, with advanced labs and facilities that help students study, carry out projects and get hands-on training. It also stands out for its partnership with Arizona State University, which offers dual-degree programs in a number of specializations. The campus includes student housing and a variety of sports and recreational facilities, along with student clubs and activities, for a complete on-campus university experience, with transportation linking the university to Cairo and Giza.', 'جامعة الجلالة هي جامعة أهلية غير هادفة للربح تقع في مدينة الجلالة، وتقدم تجربة جامعية حديثة تجمع بين التعليم التطبيقي والبحث والابتكار. تضم الجامعة أكثر من 60 برنامجا في تخصصات متنوعة، مع معامل ومرافق متطورة تساعد الطلاب على الدراسة وتنفيذ المشروعات والتدريب العملي. كما تتميز بشراكتها مع "Arizona State University" التي تتيح برامج درجات مزدوجة في عدد من التخصصات. ويضم الحرم الجامعي سكنا للطلاب ومرافق رياضية وترفيهية متنوعة، إلى جانب الأندية والأنشطة الطلابية، لتوفير تجربة جامعية متكاملة داخل الحرم، مع خدمات نقل تربط الجامعة بالقاهرة والجيزة.', NULL, NULL, NULL, '/img/universities/galala-university/logo.png', '/img/universities/galala-university/cover.jpg', 2020, 'Galala Plateau, Ain Sokhna, Suez, Egypt', 'هضبة الجلالة، العين السخنة، السويس، مصر', NULL, NULL, 3, FALSE, FALSE, FALSE, NULL, NULL, 'https://maps.google.com/?q=Galala+University', '2026-10-13T22:57:28.689Z', '2026-10-13T22:57:28.689Z', '2026-10-08T06:30:33.390Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
