INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_3d89174830354ffeb045', 'Sinai University', 'جامعة سيناء', 'SU', 'sinai-university', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'Arish', 'العريش', 'Sinai University offers accredited education with campuses serving Sinai and Canal regions.', 'جامعة سيناء هي جامعة خاصة لها فرعان في العريش والقنطرة شرق بمحافظة الإسماعيلية، وتقدم تجربة تعليمية تركز على الدراسة التطبيقية والبحث العلمي باستخدام أحدث أساليب وتقنيات التعليم. ويضم فرع القنطرة كليات طب الأسنان والصيدلة والهندسة وتكنولوجيا المعلومات وعلوم الحاسب والإعلام وإدارة الأعمال والعلاج الطبيعي، مع اهتمام بتطوير البرامج التعليمية بما يتوافق مع احتياجات سوق العمل. كما تضم الجامعة مركزا للبحث العلمي والتنمية المستدامة، ووحدات للمعامل المركزية والمشروعات البحثية والتدريب، وتوفر برامج للدراسات العليا تشمل الدبلوم والماجستير والدكتوراه. وتتميز الجامعة كذلك باستخدام اللغة الإنجليزية في التعليم، ودعم التعاون الأكاديمي والبحثي الدولي.', NULL, NULL, NULL, '/img/universities/sinai-university/logo.png', '/img/universities/sinai-university/cover.jpg', 2005, 'Arish & Qantara, Egypt', 'العريش والقنطرة، مصر', NULL, NULL, 1, FALSE, FALSE, FALSE, NULL, NULL, 'https://maps.google.com/?q=Sinai+University', '2026-10-13T22:57:28.689Z', '2026-10-13T22:57:28.689Z', '2026-10-08T01:34:38.893Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
