INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_56a1915665594b94a4fd', 'Badr University in Cairo', 'جامعة بدر بالقاهرة', 'BUC', 'badr-university-in-cairo', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'Badr City', 'مدينة بدر', 'Badr University in Cairo is a private university founded in 2010 in Badr City, Cairo Governorate. It offers a wide variety of academic programs in fields including medicine, dentistry, pharmacy, engineering and technology, physical therapy, nursing, business administration, languages and translation, arts, humanities and more. Study follows the credit-hour system, with a focus on practical application, training and skills development. The campus offers labs, learning facilities and a range of student services, alongside sports, cultural and artistic activities. The university also provides fully equipped housing for female students with round-the-clock security and support, as well as transportation linking the university to a number of areas.', 'جامعة بدر بالقاهرة هي جامعة خاصة تأسست عام 2010 وتقع في مدينة بدر بمحافظة القاهرة. تقدم الجامعة برامج أكاديمية متنوعة في مجالات تشمل الطب، وطب الفم والأسنان، والصيدلة، والهندسة والتكنولوجيا، والعلاج الطبيعي، والتمريض، وإدارة الأعمال، واللغات والترجمة، والفنون، والعلوم الإنسانية وغيرها. وتعتمد الدراسة على نظام الساعات المعتمدة، مع التركيز على التطبيق العملي والتدريب وتنمية المهارات. كما يوفر الحرم الجامعي معامل ومرافق تعليمية وخدمات طلابية متنوعة، إلى جانب أنشطة رياضية وثقافية وفنية. وتوفر الجامعة سكنا مجهزا للطالبات مع خدمات أمن ودعم على مدار الساعة، بالإضافة إلى وسائل نقل تربط الجامعة بعدد من المناطق.', NULL, NULL, 'https://www.buc.edu.eg', NULL, '/img/universities/badr-university-in-cairo/cover.jpg', 2010, 'Badr City, Cairo, Egypt', NULL, NULL, NULL, 29, TRUE, FALSE, TRUE, 30.1667, 31.7333, 'https://maps.google.com/?q=Badr+University+in+Cairo', '2026-10-13T22:56:33.432Z', '2026-10-13T22:56:33.432Z', '2026-10-08T06:36:25.409Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
