INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_666e1e2fe81f4458bdf2', 'Nahda University', 'جامعة النهضة', 'NUB', 'nahda-university', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'Beni Suef', 'بني سويف', 'Nahda University is the first private university in Upper Egypt, located in New Beni Suef City on the Cairo-Beni Suef road. It offers a university experience that combines academic study with practical application, with a variety of specializations in medical, engineering, technology, management and arts fields. Among its highlights is Nahda University Hospital, which provides a training environment for medical students, along with labs, learning equipment and a center for scientific and applied research. The university also provides equipped, air-conditioned student housing with restaurants, a cafeteria, and security and cleaning services, as well as sports fields, sports, cultural and artistic activities, and transportation linking the university to Cairo and several surrounding governorates and cities.', 'جامعة النهضة هي أول جامعة خاصة في صعيد مصر، وتقع في مدينة بني سويف الجديدة على طريق القاهرة–بني سويف. وتقدم تجربة جامعية تجمع بين الدراسة الأكاديمية والتطبيق العملي، مع تخصصات متنوعة في المجالات الطبية والهندسية والتكنولوجية والإدارية والفنية. ومن أبرز مميزاتها مستشفى جامعة النهضة التي توفر بيئة تدريبية لطلاب القطاع الطبي، إلى جانب معامل وتجهيزات تعليمية ومركز للأبحاث العلمية والتطبيقية. كما توفر الجامعة سكنًا طلابيًا مجهزًا ومكيفًا مع مطاعم وكافيتريا وخدمات أمن ونظافة، بالإضافة إلى ملاعب وأنشطة رياضية وثقافية وفنية وخدمات انتقال تربط الجامعة بالقاهرة وعدد من المحافظات والمدن المحيطة.', NULL, NULL, NULL, '/img/universities/nahda-university/logo.png', '/img/universities/nahda-university/cover.jpg', 2006, 'Beni Suef, Egypt', 'بني سويف، مصر', NULL, NULL, 50, FALSE, FALSE, FALSE, NULL, NULL, 'https://maps.google.com/?q=Nahda+University+Beni+Suef', '2026-10-13T22:57:28.689Z', '2026-10-13T22:57:28.689Z', '2026-10-08T08:23:39.801Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
