INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_6f6405011b4144eabd20', 'Zewail City of Science, Technology and Innovation', 'مدينة زويل للعلوم والتكنولوجيا والابتكار', 'Zewail', 'zewail-city-of-science-technology-and-innovation', 'NATIONAL'::"UniversityType", 'Egypt', 'مصر', '6th of October City', 'مدينة 6 أكتوبر', 'Zewail City of Science and Technology is a non-profit scientific and research institution that offers students a distinctive experience focused mainly on science, technology, research and innovation. Its University of Science and Technology offers specialized programs in engineering, science, pharmacy and medical sciences, with a strong reliance on research-based and project-based learning and lab work. The campus also stands out for its advanced research centers and labs, which let students take part in research projects in fields such as artificial intelligence, energy, water and biological sciences. The City also provides an academic environment that brings university study and scientific research together in one place, with opportunities for training and for taking part in conferences and research projects.', 'تجمع مدينة زويل بين التعليم المتقدم والبحث العلمي في مجالات التكنولوجيا والابتكار.', NULL, NULL, NULL, '/img/universities/zewail-city-of-science-technology-and-innovation/logo.png', '/img/universities/zewail-city-of-science-technology-and-innovation/cover.jpg', 2011, '6th of October City, Giza, Egypt', 'مدينة 6 أكتوبر، الجيزة، مصر', NULL, NULL, 0, FALSE, FALSE, FALSE, NULL, NULL, 'https://maps.google.com/?q=Zewail+City', '2026-10-13T22:57:28.689Z', '2026-10-13T22:57:28.689Z', '2026-10-01T08:35:51.570Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_f590aec6095a4ac88b63', 'Misr International University', 'جامعة مصر الدولية', 'MIU', 'misr-international-university-miu', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'Obour City', 'القاهرة', 'Misr International University is a private university founded in 1996 on the Cairo-Ismailia Desert Road. Teaching began with two faculties, Al-Alsun and Mass Communication, and Business Administration, before expanding to include engineering, pharmacy, computer science and dentistry, along with departments of architecture and of electronics and communications. The university focuses on integrating its academic programs with applied scientific research and student skills development, with an emphasis on innovation, entrepreneurship and professional development. It also has academic cooperation with international universities and institutions, and offers students a range of educational and community activities and services.', 'تعمل جامعة مصر الدولية من مقرها عند الكيلو 28 على طريق القاهرة الإسماعيلية منذ عام 1996، وهي من أقدم الجامعات الخاصة في مصر، وتتميز ببرامج إدارة الأعمال والصيدلة والألسن التطبيقية.', NULL, NULL, 'https://www.miuegypt.edu.eg', '/img/universities/misr-international-university-miu/logo.png', '/img/universities/misr-international-university-miu/cover.jpg', 1996, 'Obour City, Qalyubia, Egypt', NULL, NULL, NULL, 28, TRUE, FALSE, FALSE, 30.197, 31.639, 'https://maps.google.com/?q=Misr+International+University', '2026-10-13T22:56:33.432Z', '2026-10-13T22:56:33.432Z', '2026-10-04T01:29:01.099Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
