INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_8e68d213bb684056821a', 'Nile University', 'جامعة النيل', 'NU', 'nile-university', 'NATIONAL'::"UniversityType", 'Egypt', 'مصر', 'Sheikh Zayed City', 'مدينة الشيخ زايد', 'Nile University is a non-profit national university founded in 2006, and one of the universities with a particular focus on scientific research, innovation and entrepreneurship. The university relies on applied learning through real projects and hands-on training in collaboration with more than 200 industry partners. It also has specialized research centers in technology, engineering and computer science, along with a system that supports students in developing ideas and turning them into projects and startups. The university also offers full and partial scholarships based on academic excellence and merit.', 'تعمل جامعة النيل بنموذج مختلف عن قصد، فهي مؤسسة غير هادفة للربح تُعلي من شأن البحث العلمي، وتقع في مدينة الشيخ زايد، وتنظّم برامجها منذ عام 2006 في مدارس للعلوم التطبيقية بدلاً من نظام الكليات التقليدي.', NULL, NULL, 'https://www.nu.edu.eg', '/img/universities/nile-university/logo.png', '/img/universities/nile-university/cover.jpg', 2006, 'Juhayna Square, 26th of July Corridor, El Sheikh Zayed, Giza, Egypt', NULL, '16453', NULL, 5, TRUE, TRUE, TRUE, 30.0778, 30.9757, 'https://maps.google.com/?q=Nile+University+Egypt', '2026-10-13T22:56:33.432Z', '2026-10-13T22:56:33.432Z', '2026-10-04T01:35:26.846Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
