INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_7ab334845e2743f38c2a', 'Nile Valley University', 'جامعة وادي النيل', 'NVU', 'nile-valley-university', 'PRIVATE'::"UniversityType", 'Egypt', 'مصر', 'Fayoum', 'قنا', 'Nile Valley University is a new private university in Fayoum Governorate, offering a learning experience focused on preparing students for the job market through modern curricula and labs equipped with advanced teaching and research methods. The university focuses on medical and technology fields, with specializations such as dentistry, pharmacy, applied health sciences and nursing, as well as physical therapy and artificial intelligence. It also offers services that make university life easier, including transportation, on-campus internet and dedicated parking. The university also values scientific research, innovation and community partnerships, and is working towards becoming a smart campus.', 'تقدم جامعة وادي النيل تعليمًا حديثًا في المجالات الصحية والعلوم والتكنولوجيا والهندسة والرياضيات (STEM) مع تعلّم عملي ونظم حرم جامعي ذكي.', NULL, NULL, NULL, NULL, '/img/universities/nile-valley-university/cover.jpg', 2021, 'Hadayek Demo, Al-Hay Al-Momayaz, Fayoum Governorate', 'قنا، مصر', NULL, NULL, 0, FALSE, FALSE, FALSE, NULL, NULL, 'https://maps.google.com/?q=Nile+Valley+University+Qena', '2026-10-13T22:57:28.689Z', '2026-10-13T22:57:28.689Z', '2026-10-01T10:04:01.702Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country",