INSERT INTO "University" ("id", "name", "nameAr", "acronym", "slug", "type", "country", "countryAr", "city", "cityAr", "description", "descriptionAr", "aboutRich", "aboutRichAr", "websiteUrl", "logoUrl", "coverImageUrl", "establishedYear", "addressLine", "addressLineAr", "phone", "email", "viewCount", "isFeatured", "isRecommended", "isTrending", "latitude", "longitude", "googleMapsUrl", "publishedAt", "createdAt", "updatedAt") VALUES ('univ_43ca0ce261644a42894f', 'Benha National University', 'جامعة بنها الأهلية', 'BNU', 'benha-national-university', 'NATIONAL'::"UniversityType", 'Egypt', 'مصر', 'Obour City', 'مدينة العبور', 'Benha National University is a national (ahleya) university established by Presidential Decree No. 369 of 2022 and located in Obour City, Qalyubia Governorate, on a 40-feddan campus. Teaching began in the 2022/2023 academic year with four faculties and has since grown to ten: medicine, dentistry, physical therapy, engineering, applied health sciences technology, economics and business administration, computer science, veterinary medicine, visual arts and design, and energy sciences. The faculties of visual arts, veterinary medicine and energy sciences were added by a 2023 presidential decree, and applied health sciences technology opens in the 2026/2027 academic year.', 'جامعة بنها الأهلية جامعة أهلية أُنشئت بقرار رئيس الجمهورية رقم 369 لسنة 2022، وتقع في مدينة العبور بمحافظة القليوبية على مساحة 40 فدانًا. بدأت الدراسة بها في العام الجامعي 2022/2023 بأربع كليات، ثم توسعت لتضم عشر كليات هي الطب البشري وطب الأسنان والعلاج الطبيعي والهندسة وتكنولوجيا العلوم الصحية التطبيقية والاقتصاد وإدارة الأعمال وعلوم الحاسب والطب البيطري والفنون البصرية والتصميم وعلوم الطاقة. وأُضيفت كليات الفنون البصرية والطب البيطري وعلوم الطاقة بقرار جمهوري عام 2023، وتبدأ الدراسة بكلية تكنولوجيا العلوم الصحية التطبيقية في العام الجامعي 2026/2027.', NULL, NULL, 'https://bnu.edu.eg', '/img/universities/benha-national-university/logo.png', NULL, 2022, 'Entertainment District, Obour Main Axis, Obour City, Qalyubia Governorate', 'الحي الترفيهي، محور العبور الرئيسي، مدينة العبور، محافظة القليوبية', NULL, NULL, 1, FALSE, FALSE, FALSE, NULL, NULL, NULL, '2026-10-10T02:42:53.167Z', '2026-10-10T02:42:53.167Z', '2026-10-10T02:43:33.808Z') ON CONFLICT (id) DO UPDATE SET "name" = EXCLUDED."name", "nameAr" = EXCLUDED."nameAr", "acronym" = EXCLUDED."acronym", "slug" = EXCLUDED."slug", "type" = EXCLUDED."type", "country" = EXCLUDED."country", "countryAr" = EXCLUDED."countryAr", "city" = EXCLUDED."city", "cityAr" = EXCLUDED."cityAr", "description" = EXCLUDED."description", "descriptionAr" = EXCLUDED."descriptionAr", "aboutRich" = EXCLUDED."aboutRich", "aboutRichAr" = EXCLUDED."aboutRichAr", "websiteUrl" = EXCLUDED."websiteUrl", "logoUrl" = EXCLUDED."logoUrl", "coverImageUrl" = EXCLUDED."coverImageUrl", "establishedYear" = EXCLUDED."establishedYear", "addressLine" = EXCLUDED."addressLine", "addressLineAr" = EXCLUDED."addressLineAr", "phone" = EXCLUDED."phone", "email" = EXCLUDED."email", "viewCount" = EXCLUDED."viewCount", "isFeatured" = EXCLUDED."isFeatured", "isRecommended" = EXCLUDED."isRecommended", "isTrending" = EXCLUDED."isTrending", "latitude" = EXCLUDED."latitude", "longitude" = EXCLUDED."longitude", "googleMapsUrl" = EXCLUDED."googleMapsUrl", "updatedAt" = EXCLUDED."updatedAt";
